#include "cppunivariate/distributions/cmb/mle.hpp"
#include "../../../../univariateML-cpp/tests/json_loader.hpp"
#include <cstdio>
#include <chrono>
int main(){
 auto g=mltest::load_golden("univariateML-cpp/include/cppunivariate/distributions/cmb/golden.json"); std::vector<int> x;for(double v:g.data)x.push_back(int(v)); cppunivariate::ispan data{x.data(),x.size()}; int mx=*std::max_element(x.begin(),x.end()),mn=*std::min_element(x.begin(),x.end());
 for(double p:{std::numeric_limits<double>::quiet_NaN(),g.estimates.at("prob")}){auto started=std::chrono::steady_clock::now();auto full=cppunivariate::cmb_size_free_nu_mle(data,p);printf("actual status=%d size=%.0f prob=%.12g nu=%.12g logLik=%.12f elapsed=%.6f\n",int(full.fit.status),full.size,full.fit.prob,full.fit.nu,full.fit.logLik,std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count());size_t work=0; double best=-INFINITY; int bn=0; for(int N=mx;N<=mx+32;++N){auto f=cppunivariate::cmb_detail::size_candidate_rescue(data,N,p,1e-10,100,work,10000000); double u; if(f.status!=cppunivariate::CmbStatus::Ok || !cppunivariate::cmb_detail::fixed_profile_upper(data,N,f,!std::isnan(p),u)){printf("initial fail %d %zu\n",N,work);break;} work+=N+1;if(f.logLik>best){best=f.logLik;bn=N;}} if(std::isnan(p)) { std::vector<double> d(x.begin(),x.end()); cppunivariate::CmpFitControl ctl; ctl.tol=1e-10;ctl.maxit=100; const size_t count=101;ctl.max_terms=std::min(size_t(10000),(size_t(10000000)-work)/(2*count*count));if(ctl.max_terms>=2){const auto cmp=cppunivariate::cmp_mle({d.data(),d.size()},ctl);work+=cmp.work;printf("CMP face status=%d logLik=%.12g work=%zu\n",int(cmp.status),cmp.logLik,cmp.work);}}
 double B=best-1e-8*(1+std::abs(best)),w=double(mx-mn-1)/(mx-mn),left=w*std::lgamma(mn+1.),right=(1-w)*std::lgamma(mx+1.),middle=std::lgamma(mn+2.),delta=left+right-middle-1e-10*(1+std::abs(left)+std::abs(right)+std::abs(middle)); double lu=cppunivariate::cmb_detail::observed_log_lower(data,mn,B),lv=cppunivariate::cmb_detail::observed_log_lower(data,mx,B),rem=std::min(1.,1-std::exp(lu)-std::exp(lv)+1e-9),uj=std::min(std::log(rem),cppunivariate::cmb_detail::observed_log_upper(data,mn+1,B)),pos=std::max(0.,(uj-w*lu-(1-w)*lv)/delta); printf("p=%g mn=%d mx=%d bestN=%d best=%.12f work=%zu pos=%g\n",p,mn,mx,bn,best,work,pos);for(int K=std::max(mx+1,8);K<=4096;K*=2){double trunc=0;bool ok=cppunivariate::cmb_detail::truncated_upper(data,K,trunc,work,10000000);printf("K=%d upper=%g ok=%d work=%zu\n",K,trunc,ok,work);if(!ok||trunc>=B)continue; double neg=-lv/std::log(double(K));auto bound=[&](int N){double ck=0,s=0;for(int j=0;j<K;++j)ck-=std::log1p(-double(j)/N);for(int v:x)for(int j=0;j<v;++j)s-=std::log1p(-double(j)/N);return trunc+std::max(pos*x.size()*ck,neg*s);};int lo=std::max(K,mx+33),hi=lo;while(bound(hi)>=B&&hi<10000000)hi=hi>5000000?10000000:hi*2;while(hi-lo>1){int m=lo+(hi-lo)/2;if(bound(m)<B)hi=m;else lo=m;}printf("cutoff=%d bound=%g\n",hi,bound(hi));
    { size_t bw=work; int excluded=0,leaves=0,solves=0; std::vector<std::pair<int,int>> blocks{{mx+33,hi-1}};
      while(!blocks.empty()) {auto block=blocks.back();blocks.pop_back();int L=block.first,R=block.second;
        if(L<K){++leaves;if(L<R)blocks.push_back({L+1,R});continue;}
        double anchor=0;if(!cppunivariate::cmb_detail::truncated_upper(data,K,anchor,bw,10000000,L)){printf("block solve failed L=%d work=%zu\n",L,bw);break;}++solves;bw+=K+1;
        double d=0,sum=0;std::vector<double> delta(K+1,0);for(int k=1;k<=K;++k){d+=std::log1p(-double(k-1)/R)-std::log1p(-double(k-1)/L);delta[k]=d;}for(int v:x)sum+=delta[v];
        double extra=std::max(pos*sum,neg*(x.size()*d-sum));double u=anchor+extra+1e-9*(1+std::abs(anchor)+std::abs(extra));
        if(u<B)++excluded;else if(L==R)++leaves;else {int mid=L+(R-L)/2;blocks.push_back({mid+1,R});blocks.push_back({L,mid});}
      }printf("blocks K=%d excluded=%d singleton=%d solves=%d work_before_singletons=%zu\n",K,excluded,leaves,solves,bw);
    }
    for(int N=mx+33;N<hi;++N){auto f=cppunivariate::cmb_detail::size_candidate_rescue(data,N,p,1e-10,100,work,10000000);double u=0;bool ok2=f.status==cppunivariate::CmbStatus::Ok && cppunivariate::cmb_detail::fixed_profile_upper(data,N,f,!std::isnan(p),u);if(!ok2||std::abs(u-f.logLik)>1e-8*(1+std::abs(f.logLik))){printf("enumeration failed N=%d status=%d cert=%d gap=%g work=%zu\n",N,int(f.status),ok2,u-f.logLik,work);break;}work+=N+1;}break;}}
}
